const html = items[0].json.data;
const dates = [];
const regex = /href="[^"]*Bim_AktuelTarihKey=(\d+)"[^>]*>([\s\S]*?)<\/a>/g;
let match;
while ((match = regex.exec(html)) !== null) {
  let key = match[1];
  let dateText = match[2].trim().replace(/<[^>]*>?/gm, '');
  if (dateText.toLowerCase().includes("mobil") || key === "100") continue;
  let videoTitleContext = dateText.includes("-") ? "Haftanın İndirim Fırsatları" : "Aktüel Ürünler Kataloğu";
  if (!dates.some(d => d.json.key === key)) {
      dates.push({
          json: {
              key: key,
              date_text: dateText,
              full_url: `https://www.bim.com.tr/Categories/100/aktuel-urunler.aspx?Bim_AktuelTarihKey=${key}`,
              video_suffix: videoTitleContext 
          }
      });
  }
}
dates.sort((a, b) => parseInt(a.json.key) - parseInt(b.json.key));
if (dates.length === 0) return [];
return dates;

const html = items[0].json.data;
const results = [];
const parts = html.split('<div class="product');
let validCount = 0;
function toTitleCase(str) { return str.replace(/\S+/g, function(txt) { return txt.charAt(0).toLocaleUpperCase('tr-TR') + txt.slice(1).toLocaleLowerCase('tr-TR'); }); }
function generateTags(title) { let tags = ["#BİM", "#BimAktüel", "#İndirim", "#Kampanya"]; let cleanTitle = title.replace(/[^a-zA-Z0-9çğıöşüÇĞİÖŞÜ]/g, ""); if (cleanTitle.length < 20 && cleanTitle.length > 3) tags.push("#" + cleanTitle); return tags.join(" "); }

for (let i = 1; i < parts.length; i++) {
    const part = parts[i];
    const hasPrice = part.match(/class="[^"]*(price|fiyat)/i);
    if (!hasPrice) continue; 
    const titleMatch = part.match(/<h2 class="title">([^<]*)<\/h2>/i);
    let title = titleMatch ? titleMatch[1].trim() : null;
    if (!title) continue;
    let rawPrice = '';
    const priceMatch = part.match(/class="(?:price|fiyat)[^>]*>([\s\S]*?)<\/div>/i);
    if (priceMatch && priceMatch[1]) rawPrice = priceMatch[1].replace(/<[^>]*>?/gm, '').trim();
    if (rawPrice.endsWith(',')) rawPrice = rawPrice.slice(0, -1);
    let visualPrice = rawPrice; 
    let cleanNumbers = rawPrice.replace(/\./g, '');
    let priceParts = cleanNumbers.split(',');
    let lira = priceParts[0].trim();
    let kurus = (priceParts.length > 1) ? priceParts[1].trim() : '00';
    let spokenPriceText = "";
    if (!isNaN(lira) && lira !== "") spokenPriceText += `${lira} Lira`;
    if (kurus !== '00' && kurus !== '' && !isNaN(kurus)) spokenPriceText += ` ${kurus} Kuruş`;
    let spokenTitle = toTitleCase(title);
    spokenTitle = spokenTitle.replace(/\bkg\b/gi, ' Kilogram ').replace(/\bgr\b/gi, ' Gram ').replace(/\bcm\b/gi, ' Santim ').replace(/\blt\b/gi, ' Litre ').replace(/\bml\b/gi, ' Mililitre ').replace(/\badet\b/gi, ' tane ');
    spokenTitle = spokenTitle.replace(/\bV(\d+)/gi, 'Ve $1'); 
    while (/\d\.\d/.test(spokenTitle)) spokenTitle = spokenTitle.replace(/(\d)\.(\d)/g, '$1 Nokta $2');
    let safeSpokenTitle = spokenTitle.replace(/["']/g, "");
    let ttsText = `${safeSpokenTitle} ${spokenPriceText}`; 
    let autoTags = generateTags(title);
    let description = `${spokenTitle} fiyatı: ${visualPrice} TL! \n${autoTags}`;
    const xsrcMatch = part.match(/xsrc="([^"]*)"/i);
    const srcMatch = part.match(/src="([^"]*)"/i);
    let imageUrl = (xsrcMatch && xsrcMatch[1]) ? xsrcMatch[1] : (srcMatch && srcMatch[1] ? srcMatch[1] : null);
    if (!imageUrl) continue;
    if (!imageUrl.startsWith('http')) { if (!imageUrl.startsWith('/')) imageUrl = '/' + imageUrl; imageUrl = 'https://www.bim.com.tr' + imageUrl; }
    const safeTitle = title.replace(/['":]/g, '');
    const safePrice = visualPrice.replace(/['":]/g, '') + " TL"; 
    results.push({
        json: { product_name: safeTitle, product_price: safePrice, tts_text: ttsText, video_tags: autoTags, video_description: description, product_image: imageUrl, imgName: `/files/img_${validCount}.jpg`, audioName: `/files/audio_${validCount}.mp3`, clipName: `/files/clip_${validCount}.mp4`, index: validCount }
    });
    validCount++;
}
return results;

const items = $('Veri ve Fiyat Ayıkla1').all(); 
let fileListContent = '';
let uniqueTags = new Set();
let productList = [];
uniqueTags.add('BİM'); uniqueTags.add('Aktüel'); uniqueTags.add('İndirim'); uniqueTags.add('Kampanya');
const today = new Date().toLocaleDateString('tr-TR');
if (!items.length) return [];
for (const item of items) {
  if (item.json.clipName) fileListContent += `file '${item.json.clipName}'\n`;
  if (item.json.product_name) productList.push(`- ${item.json.product_name}`);
  if (item.json.video_tags) {
      const tags = item.json.video_tags.split(' ');
      tags.forEach(tag => {
          let cleanTag = tag.replace(/[^a-zA-Z0-9çğıöşüÇĞİÖŞÜ]/g, '').trim();
          if(cleanTag.length > 1) uniqueTags.add(cleanTag);
      });
  }
}
let finalTagsString = Array.from(uniqueTags).join(',');
if (finalTagsString.length > 400) { finalTagsString = finalTagsString.substring(0, 400); finalTagsString = finalTagsString.substring(0, finalTagsString.lastIndexOf(',')); }
const descriptionHashtags = Array.from(uniqueTags).map(t => `#${t}`).join(' ');
const finalDescription = `BİM Aktüel Ürünler Kataloğu (${today})\n\nBu hafta BİM mağazalarına gelecek olan aktüel fırsat ürünlerini derledik. İyi seyirler!\n\n📋 Ürün Listesi:\n${productList.join('\n')}\n\nDaha fazlası için abone olun! 🔔\n\n${descriptionHashtags}`;
const binaryData = Buffer.from(fileListContent).toString('base64');
return {
  json: { success: true, final_description: finalDescription, final_tags: finalTagsString },
  binary: { data: { data: binaryData, mimeType: 'text/plain', fileName: 'clips_list.txt' } }
};

const items = $input.all();
for (const item of items) {
  if (item.binary && item.binary.data) {
    item.binary.data.mimeType = 'video/mp4';
    item.binary.data.fileExtension = 'mp4';
    if (!item.binary.data.fileName) item.binary.data.fileName = 'bim_video.mp4';
  }
}
return items;

